// Acceptance tests for the change request:
//   "I want a home screen. Show me how many clients and projects I have. Show me how much money I
//    am still owed."
//
// A new dashboard screen, reached from the nav (nav-dashboard), surfaces three figures:
//   - how many CLIENTS there are              -> dashboard-clients-count
//   - how many PROJECTS there are             -> dashboard-projects-count
//   - how much money is STILL OWED            -> dashboard-outstanding-total
// "Still owed" is the sum of the UNPAID invoice amounts across every project — invoices already
// marked PAID are not owed and must not count (status is UNPAID/PAID, see invoice-paid.spec.ts).
//
// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed. Seed honours
// clients: { id, name, email }, projects: { id, clientId, name } and invoices: { id, projectId,
// amount, status }.
//
// Counts are whole numbers asserted with toContainText so a label ("2 clients") still passes; the
// figures are chosen distinct so none is a substring of another. The outstanding total is asserted
// with toContainText so whatever display format the feature chooses (plain / decimal / currency)
// passes — amounts are picked so the owed total is not a substring of any other figure on the page.
import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

// Reach the dashboard through its nav link rather than assuming its URL — the nav entry is the
// stable contract (nav-dashboard), the concrete path is the feature's own choice.
async function openDashboard(page: import('@playwright/test').Page) {
  await page.goto('/');
  await expect(page.getByTestId('app-root')).toBeVisible();
  await page.getByTestId('nav-dashboard').click();
  await expect(page.getByTestId('dashboard-page')).toBeVisible();
  await expect(page.getByTestId('dashboard')).toBeVisible();
}

test.describe('dashboard home screen', () => {
  test('reaches the dashboard from the nav', async ({ page }) => {
    await resetAndSeed({ clients: [], projects: [], invoices: [] });

    await page.goto('/');
    await expect(page.getByTestId('app-root')).toBeVisible();

    await page.getByTestId('nav-dashboard').click();

    await expect(page.getByTestId('dashboard-page')).toBeVisible();
    await expect(page.getByTestId('dashboard')).toBeVisible();
  });

  test('shows how many clients and projects there are, and how much is still owed', async ({ page }) => {
    await resetAndSeed({
      clients: [
        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
        { id: 2, name: 'Globex', email: 'hello@globex.example' },
      ],
      projects: [
        { id: 1, clientId: 1, name: 'Website redesign' },
        { id: 2, clientId: 1, name: 'Mobile app' },
        { id: 3, clientId: 2, name: 'Warehouse automation' },
      ],
      invoices: [
        // Unpaid invoices across several projects -> still owed = 120 + 300 + 55 = 475.
        { id: 1, projectId: 1, amount: 120, status: 'UNPAID' },
        { id: 2, projectId: 1, amount: 300, status: 'UNPAID' },
        { id: 3, projectId: 3, amount: 55, status: 'UNPAID' },
        // Already PAID -> not owed, must NOT be counted into the outstanding total.
        { id: 4, projectId: 2, amount: 999, status: 'PAID' },
      ],
    });

    await openDashboard(page);

    // The data has loaded: neither the loading nor the error state remains.
    await expect(page.getByTestId('dashboard-loading')).toHaveCount(0);
    await expect(page.getByTestId('dashboard-error')).toHaveCount(0);

    // Two clients, three projects.
    await expect(page.getByTestId('dashboard-clients-count')).toContainText('2');
    await expect(page.getByTestId('dashboard-projects-count')).toContainText('3');

    // Still owed is the sum of the UNPAID amounts only (475), not including the paid 999.
    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('475');
    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('999');
  });

  test('a paid invoice is not money still owed', async ({ page }) => {
    // Every invoice is PAID, so nothing is owed even though invoices exist.
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
      invoices: [
        { id: 1, projectId: 1, amount: 120, status: 'PAID' },
        { id: 2, projectId: 1, amount: 300, status: 'PAID' },
      ],
    });

    await openDashboard(page);

    await expect(page.getByTestId('dashboard-clients-count')).toContainText('1');
    await expect(page.getByTestId('dashboard-projects-count')).toContainText('1');

    // Nothing is owed: the total reflects 0 and does not include any paid amount.
    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('0');
    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('120');
    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('300');
    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('420');
  });

  test('with no data at all the figures are zero', async ({ page }) => {
    await resetAndSeed({ clients: [], projects: [], invoices: [] });

    await openDashboard(page);

    await expect(page.getByTestId('dashboard-error')).toHaveCount(0);

    await expect(page.getByTestId('dashboard-clients-count')).toContainText('0');
    await expect(page.getByTestId('dashboard-projects-count')).toContainText('0');
    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('0');
  });
});
// Acceptance tests for the change request:
//   "When I open a project I want to see its invoices. Show me what they add up to. Let me add a
//    new invoice for an amount."
//
// Opening a project (project-open-<id> from the projects list) reaches that project's detail page.
// The detail page lists the project's OWN invoices (each with its amount), shows what they ADD UP
// TO, and offers a form to add a new invoice for an amount. After adding, the new invoice appears
// and the total reflects it.
//
// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the add flow is
// driven through the form. Seed honours clients: { id, name, email }, projects: { id, clientId,
// name } and invoices: { id, projectId, amount }.
//
// Amounts are asserted with toContainText so the test tolerates the display format the feature
// chooses (plain, decimal or currency-prefixed) — the amounts are picked so no value is a substring
// of another or of the total.
import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test.describe('project invoices', () => {
  test('opening a project shows its invoices and what they add up to', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [
        { id: 1, clientId: 1, name: 'Website redesign' },
        { id: 2, clientId: 1, name: 'Warehouse automation' },
      ],
      invoices: [
        { id: 1, projectId: 1, amount: 120 },
        { id: 2, projectId: 1, amount: 300 },
        // Belongs to a DIFFERENT project — it must not appear or count toward project 1's total.
        { id: 3, projectId: 2, amount: 999 },
      ],
    });

    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();

    await expect(page.getByTestId('project-detail-page')).toBeVisible();
    await expect(page.getByTestId('project-invoices-table')).toBeVisible();

    // Project 1's own invoices, each showing its amount.
    const first = page.getByTestId('invoice-row-1');
    await expect(first).toBeVisible();
    await expect(first.getByTestId('invoice-amount')).toContainText('120');

    const second = page.getByTestId('invoice-row-2');
    await expect(second).toBeVisible();
    await expect(second.getByTestId('invoice-amount')).toContainText('300');

    // The other project's invoice is not shown here.
    await expect(page.getByTestId('invoice-row-3')).toHaveCount(0);

    // What they add up to: 120 + 300 = 420 (and NOT including the other project's 999).
    await expect(page.getByTestId('project-invoices-total')).toContainText('420');
    await expect(page.getByTestId('project-invoices-total')).not.toContainText('999');
  });

  test('adds a new invoice for an amount, which then appears and is added into the total', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
      invoices: [],
    });

    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();

    await expect(page.getByTestId('project-detail-page')).toBeVisible();
    await expect(page.getByTestId('invoice-form')).toBeVisible();
    // No invoices seeded, so no invoice rows yet.
    await expect(page.getByTestId('invoice-amount')).toHaveCount(0);

    await page.getByTestId('invoice-form-amount').fill('250');
    await page.getByTestId('invoice-form-submit').click();

    // Reset RESTART IDENTITY + empty invoices seed => the first created invoice has id 1.
    const row = page.getByTestId('invoice-row-1');
    await expect(row).toBeVisible();
    await expect(row.getByTestId('invoice-amount')).toContainText('250');

    // The newly added amount is what the invoices add up to.
    await expect(page.getByTestId('project-invoices-total')).toContainText('250');
  });

  test('a freshly added invoice adds onto the existing total', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
      invoices: [{ id: 1, projectId: 1, amount: 120 }],
    });

    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();

    await expect(page.getByTestId('project-detail-page')).toBeVisible();
    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toContainText('120');
    await expect(page.getByTestId('project-invoices-total')).toContainText('120');

    await page.getByTestId('invoice-form-amount').fill('300');
    await page.getByTestId('invoice-form-submit').click();

    // Both invoices now listed, and the total is 120 + 300 = 420.
    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toContainText('120');
    await expect(page.getByTestId('invoice-row-2').getByTestId('invoice-amount')).toContainText('300');
    await expect(page.getByTestId('project-invoices-total')).toContainText('420');
  });
});
// Acceptance tests for the change request:
//   "Let me mark an invoice as paid. Keep a record every time I do so I can check back later."
//
// On a project's detail page each invoice shows its status (invoice-status) and offers a control to
// mark it paid (invoice-pay-<id>). Marking an invoice paid flips THAT invoice's status to paid and
// appends one audit record — INVOICE_PAID id=<id> amount=<amount> — so the action can be checked
// back later. Marking one invoice must not touch its siblings, and each marking writes its own
// record ("every time I do").
//
// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
// (auditLines()). Data is arranged via resetAndSeed; the pay flow is driven through the UI.
// Seed honours invoices: { id, projectId, amount, status }.
//
// The paid label is asserted case-insensitively (/^paid$/i) so the test tolerates whichever casing
// the feature renders (Paid / PAID / paid). The audit amount is matched with an optional trailing
// ".00" so a plain or two-decimal rendering both pass. Amounts are chosen as distinct whole numbers
// so no value is a substring of another.
import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';
import { auditLines } from '../support/audit';

test.describe('mark invoice paid', () => {
  test('marking an unpaid invoice paid flips its status and records it', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
      invoices: [{ id: 1, projectId: 1, amount: 120, status: 'UNPAID' }],
    });

    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();

    await expect(page.getByTestId('project-detail-page')).toBeVisible();

    const row = page.getByTestId('invoice-row-1');
    await expect(row).toBeVisible();
    // The invoice surfaces a status, and a control to mark it paid.
    await expect(row.getByTestId('invoice-status')).toBeVisible();
    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();

    // reset cleared the audit file — nothing has been marked paid yet.
    expect(auditLines()).toEqual([]);

    await page.getByTestId('invoice-pay-1').click();

    // The invoice's status reflects that it is now paid.
    await expect(row.getByTestId('invoice-status')).toHaveText(/^paid$/i);

    // And exactly one record was kept for the action, naming the invoice and its amount.
    await expect
      .poll(() => auditLines().filter((l) => /^INVOICE_PAID id=1 amount=120(\.0+)?$/.test(l)))
      .toHaveLength(1);
    expect(auditLines()).toHaveLength(1);
  });

  test('keeps a separate record each time, and marking one leaves the others untouched', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
      invoices: [
        { id: 1, projectId: 1, amount: 120, status: 'UNPAID' },
        { id: 2, projectId: 1, amount: 80, status: 'UNPAID' },
      ],
    });

    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();
    await expect(page.getByTestId('project-detail-page')).toBeVisible();

